#pragma once

#include <optional>
#include <string_view>
#include <cstdint>

struct mCaptchaResult {
    uint64_t nonce;
    __uint128_t score;
};

/**
 * @brief Perform the mCaptcha PoW scheme on the GPU using as many threads as possible
 * @param salt The 'salt' string set in the mCaptcha instance's settings. This is a utf-8 string given as part of the initiating request
 * @param phrase A 32 character alphanumeric string randomly generated by mCaptcha for each attempt. Also utf-8 encoded.
 * @param difficulty The 'difficulty' given by the initiating request
 * @param nonce_max The largest nonce to try in the search. To prevent giving up, set this to the unsigned 64-bit maximum.
 * @returns The nonce and score of the successful hash, if one one was found within the nonce range
 */
std::optional<struct mCaptchaResult> do_mCaptcha_gpu(std::u8string_view salt, std::u8string_view phrase, uint32_t difficulty, uint64_t nonce_max);

/**
 * @brief Perform the mCaptcha PoW scheme on the GPU using as many threads as possible
 * @param salt The 'salt' string set in the mCaptcha instance's settings. This is a utf-8 string given as part of the initiating request
 * @param phrase A 32 character alphanumeric string randomly generated by mCaptcha for each attempt. Also utf-8 encoded.
 * @param difficulty The 'difficulty' given by the initiating request
 * @param nonce_max The largest nonce to try in the search. To prevent giving up, set this to the unsigned 64-bit maximum.
 * @returns The nonce and score of the successful hash, if one one was found within the nonce range
 */
std::optional<mCaptchaResult> do_mCaptcha_singlethreaded_cpu(std::u8string_view salt, std::u8string_view phrase, uint32_t difficulty, uint64_t nonce_max);